[
    {
        "title": "求k",
        "description": "将点 $A(2,4)$ 代入 $y=\\frac{k}{x}$，得 $4=\\frac{k}{2}$，所以 $k=8$。",
        "bubbleText": "先把点 A 代进去，反比例函数里的 $k$ 就能直接算出来。",
        "bubblePos": {
            "x": 24.0,
            "y": 24.0
        },
        "arrowTarget": {
            "x": 520.0,
            "y": 276.0
        }
    },
    {
        "title": "列方程组",
        "description": "把 $A(2,4)$、$B(-1,-2)$ 代入一次函数 $y=mx+n$，得到方程组 $\\begin{cases}4=2m+n\\-2=-m+n\\end{cases}$。",
        "bubbleText": "两点都在直线上，所以一次函数也要同时经过它们。",
        "bubblePos": {
            "x": 24.0,
            "y": 24.0
        },
        "arrowTarget": {
            "x": 514.0,
            "y": 296.0
        }
    },
    {
        "title": "求一次函数",
        "description": "解方程组得 $m=2$，$n=0$，所以一次函数为 $y=2x$。",
        "bubbleText": "把两条信息合起来，直线的式子就出来了。",
        "bubblePos": {
            "x": 24.0,
            "y": 24.0
        },
        "arrowTarget": {
            "x": 570.0,
            "y": 287.0
        }
    },
    {
        "title": "写出反比例式",
        "description": "由 $k=8$，反比例函数为 $y=\\frac{8}{x}$。",
        "bubbleText": "反比例函数也就只差把 $k$ 填进去。",
        "bubblePos": {
            "x": 24.0,
            "y": 24.0
        },
        "arrowTarget": {
            "x": 575.0,
            "y": 264.0
        }
    },
    {
        "title": "求三角形面积",
        "description": "用坐标法：$S_{\\triangle AOB}=\\frac12|x_Ay_B-y_Ax_B|=\\frac12|2\\cdot(-2)-4\\cdot(-1)|=2$。",
        "bubbleText": "O 是原点，和 A、B 组成的三角形可以直接用坐标求面积。",
        "bubblePos": {
            "x": 24.0,
            "y": 24.0
        },
        "arrowTarget": {
            "x": 555.0,
            "y": 494.0
        }
    },
    {
        "title": "核对面积",
        "description": "再看底和高：$OA=2\\sqrt5$，$OB=\\sqrt5$，对应面积仍为 $2$，结果一致。",
        "bubbleText": "换一种算法，答案还是一样，这就说明前面的结果稳了。",
        "bubblePos": {
            "x": 24.0,
            "y": 24.0
        },
        "arrowTarget": {
            "x": 620.0,
            "y": 406.0
        }
    },
    {
        "title": "写不等式解集",
        "description": "比较图象可得 $\\frac{8}{x}>2x$ 的解集为 $(-1,0)\\cup(0,2)$。",
        "bubbleText": "谁在上面，谁的函数值就更大；从图上直接看区间。",
        "bubblePos": {
            "x": 24.0,
            "y": 24.0
        },
        "arrowTarget": {
            "x": 520.0,
            "y": 250.0
        }
    }
]
